&lt;table class=&quot;Bestiaire&quot;&gt;&lt;tr&gt;&lt;td&gt;
&lt;div class=&quot;BD&quot;&gt;
&lt;div class=&quot;BDtitre&quot;&gt;Acolyte&lt;div style=&quot;float:right;&quot;&gt;FP 1/3&lt;/div&gt;&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;i&gt;Source : &lt;a class=&quot;pagelink&quot; href=&quot;Manuel-Des-Pnj-(Contenu).html&quot; title=&quot;Manuel des PNJ (Contenu)&quot;&gt;Manuel des PNJ p. 244&lt;/a&gt;&lt;/i&gt;
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;PX&lt;/b&gt; 135
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;a class=&quot;pagelink&quot; href=&quot;Humain.html&quot; title=&quot;Les humains&quot;&gt;Humain&lt;/a&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Adepte.html&quot; title=&quot;L&amp;#39;adepte&quot;&gt;adepte&lt;/a&gt; 1
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;a class=&quot;pagelink&quot; href=&quot;Type-Humano&#239;de.html&quot; title=&quot;Humano&#239;de&quot;&gt;Humano&#239;de&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Sous-Type-Humain.html&quot; title=&quot;Humain (sous-type)&quot;&gt;humain&lt;/a&gt;) de taille M, N
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Init&lt;/b&gt; +1 ; &lt;b&gt;Sens&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Perception.html&quot; title=&quot;Perception&quot;&gt;Perception&lt;/a&gt; +1
&lt;/div&gt;
&lt;div class=&quot;BDsoustitre&quot;&gt;D&#233;fense&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;CA&lt;/b&gt; 14, contact 11, pris au d&#233;pourvu 13 (armure +3, Dex +1)
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;pv&lt;/b&gt; 5 (1d6+2)
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;R&#233;f&lt;/b&gt; +1, &lt;b&gt;Vig&lt;/b&gt; -1, &lt;b&gt;Vol&lt;/b&gt; +3
&lt;/div&gt;
&lt;div class=&quot;BDsoustitre&quot;&gt;Attaque&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;VD&lt;/b&gt; 9 m
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Corps &#224; corps&lt;/b&gt; morgenstern, +0 (1d8) ou dague en argent, +0 (1d4/19–20)
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Distance&lt;/b&gt; dague en argent, +1 (1d4/19–20)
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Sorts d&#39;adepte pr&#233;par&#233;s&lt;/b&gt;  (&lt;a class=&quot;pagelink&quot; href=&quot;Lancer-Des-Sorts#Nls.html&quot; title=&quot;NLS&quot;&gt;NLS&lt;/a&gt; 1 ; &lt;a class=&quot;pagelink&quot; href=&quot;Lancer-Des-Sorts#Concentration.html&quot; title=&quot;Concentration&quot;&gt;concentration&lt;/a&gt; +2)
&lt;/div&gt;
&lt;div class=&quot;BDsorts&quot;&gt;
1er — &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;B&#233;n&#233;diction.html&quot; title=&quot;B&#233;n&#233;diction&quot;&gt;b&#233;n&#233;diction&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Soins-L&#233;gers.html&quot; title=&quot;Soins l&#233;gers&quot;&gt;soins l&#233;gers&lt;/a&gt;&lt;/i&gt;
&lt;/div&gt;
&lt;div class=&quot;BDsorts&quot;&gt;
0 (&#224; volont&#233;) — &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Assistance-Divine.html&quot; title=&quot;Assistance divine&quot;&gt;assistance divine&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Lumi&#232;re.html&quot; title=&quot;Lumi&#232;re&quot;&gt;lumi&#232;re&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;R&#233;paration.html&quot; title=&quot;R&#233;paration&quot;&gt;r&#233;paration&lt;/a&gt;&lt;/i&gt;
&lt;/div&gt;
&lt;div class=&quot;BDsoustitre&quot;&gt;Tactique&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Pendant le combat&lt;/b&gt; L’adepte lit son &lt;i&gt;parchemin de sommeil&lt;/i&gt; et ordonne &#224; son chien d’attaquer. Il lance ensuite &lt;i&gt;b&#233;n&#233;diction&lt;/i&gt; et attaque avec son morgenstern.
&lt;/div&gt;
&lt;div class=&quot;BDsoustitre&quot;&gt;Statistiques&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;For&lt;/b&gt; 10, &lt;b&gt;Dex&lt;/b&gt; 12, &lt;b&gt;Con&lt;/b&gt; 8, &lt;b&gt;Int&lt;/b&gt; 9, &lt;b&gt;Sag&lt;/b&gt; 13, &lt;b&gt;Cha&lt;/b&gt; 10
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;BBA&lt;/b&gt; +0 ; &lt;b&gt;BMO&lt;/b&gt; +0 ; &lt;b&gt;DMD&lt;/b&gt; 11
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Dons&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Robustesse.html&quot; title=&quot;Robustesse&quot;&gt;Robustesse&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Talent.html&quot; title=&quot;Talent&quot;&gt;Talent&lt;/a&gt; (Dressage)
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Comp&#233;tences&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Art-De-La-Magie.html&quot; title=&quot;Art de la magie&quot;&gt;Art de la magie&lt;/a&gt; +3, &lt;a class=&quot;pagelink&quot; href=&quot;Dressage.html&quot; title=&quot;Dressage&quot;&gt;Dressage&lt;/a&gt; +7, &lt;a class=&quot;pagelink&quot; href=&quot;Premiers-Secours.html&quot; title=&quot;Premiers secours&quot;&gt;Premiers secours&lt;/a&gt; +7
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Langues&lt;/b&gt; commun
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;&#201;quipement de combat&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Feu-Gr&#233;geois-(Objet).html&quot; title=&quot;Feu gr&#233;geois&quot;&gt;feu gr&#233;geois&lt;/a&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Parchemins-Magiques.html&quot; title=&quot;Les parchemins magiques&quot;&gt;parchemin&lt;/a&gt; de &lt;a class=&quot;pagelink&quot; href=&quot;Soins-L&#233;gers.html&quot; title=&quot;Soins l&#233;gers&quot;&gt;soins l&#233;gers&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Parchemins-Magiques.html&quot; title=&quot;Les parchemins magiques&quot;&gt;parchemin&lt;/a&gt; de &lt;a class=&quot;pagelink&quot; href=&quot;Sommeil.html&quot; title=&quot;Sommeil&quot;&gt;sommeil&lt;/a&gt;&lt;/i&gt; ; &lt;b&gt;&#201;quipement divers&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Allume-Feu-(Objet).html&quot; title=&quot;Allume-feu&quot;&gt;allume-feu&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Armure-De-Cuir-(Armure).html&quot; title=&quot;Armure de cuir&quot;&gt;armure de cuir&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;B&#226;ton-Fumig&#232;ne-(Objet).html&quot; title=&quot;B&#226;ton fumig&#232;ne&quot;&gt;b&#226;ton fumig&#232;ne&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Dague-(Arme).html&quot; title=&quot;Dague&quot;&gt;dague&lt;/a&gt; en &lt;a class=&quot;pagelink&quot; href=&quot;Mat&#233;riaux-Sp&#233;ciaux#Argent.html&quot; title=&quot;argent&quot;&gt;argent&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Chien-(Objet).html&quot; title=&quot;Chien&quot;&gt;chien de garde&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Morgenstern-(Arme).html&quot; title=&quot;Morgenstern&quot;&gt;morgenstern&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Sacoche-&#192;-Composantes-(Objet).html&quot; title=&quot;Sacoche &#224; composantes&quot;&gt;sacoche &#224; composantes&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Symbole-Sacr&#233;-(Objet).html&quot; title=&quot;Symbole sacr&#233;&quot;&gt;symbole sacr&#233; en argent&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Trousse-De-Premiers-Secours-(Objet).html&quot; title=&quot;Trousse de premiers secours&quot;&gt;trousse de premiers secours&lt;/a&gt;, 9 po
&lt;/div&gt;
&lt;/div&gt;
&lt;/td&gt;&lt;td&gt;&lt;div&gt;L’acolyte commence tout juste &#224; d&#233;couvrir les myst&#232;res de sa religion et n’est pas encore marqu&#233; par le fanatisme ardent des membres les plus endoctrin&#233;s. Il a soif d’apprendre mais, du fait de ses enseignements incomplets, il se laisse plus facilement influencer par les discours contraires &#224; ses id&#233;es.&lt;br /&gt;&lt;br /&gt;Les villages comptant davantage d’adeptes que de pr&#234;tres sont souvent primitifs et recul&#233;s. Leurs pratiques religieuses peuvent appara&#238;tre comme un &#233;trange d&#233;riv&#233; ou un aspect h&#233;r&#233;tique d’une religion majeure, plus faible que la forme commune mais donnant acc&#232;s &#224; des sorts normalement inaccessibles aux vrais pr&#234;tres (comme cr&#233;ation mineure et sommeil). Un individu form&#233; par un pr&#234;tre mais manifestant des pouvoirs d’adepte risque d’&#234;tre vu comme un blasph&#233;mateur ou une sorci&#232;re et se faire bannir.&lt;br /&gt;&lt;br /&gt;&lt;/div&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;
